use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Replace any references to `super::X` in `original` with `super::super::X`."] fn supersuperfy (original : & Type , levels : usize) -> Type { let mut output = original . clone () ; fn recurse (t : & mut Type , levels : usize) { match t { Type :: Slice (s) => { recurse (s . elem . as_mut () , levels) ; } Type :: Array (a) => { recurse (a . elem . as_mut () , levels) ; } Type :: Ptr (p) => { recurse (p . elem . as_mut () , levels) ; } Type :: Reference (r) => { recurse (r . elem . as_mut () , levels) ; } Type :: BareFn (bfn) => { if let ReturnType :: Type (_ , ref mut bt) = bfn . output { recurse (bt . as_mut () , levels) ; } for input in bfn . inputs . iter_mut () { recurse (& mut input . ty , levels) ; } } Type :: Tuple (tuple) => { for elem in tuple . elems . iter_mut () { recurse (elem , levels) ; } } Type :: Path (type_path) => { let added = supersuperfy_path (& mut type_path . path , levels) ; if let Some (ref mut qself) = type_path . qself { recurse (qself . ty . as_mut () , levels) ; qself . position += added ; } } Type :: Paren (p) => { recurse (p . elem . as_mut () , levels) ; } Type :: Group (g) => { recurse (g . elem . as_mut () , levels) ; } Type :: Macro (_) | Type :: Verbatim (_) => { compile_error (t . span () , "mockall_derive does not support this type in this position" ,) ; } Type :: TraitObject (tto) => { for bound in tto . bounds . iter_mut () { if let TypeParamBound :: Trait (tb) = bound { supersuperfy_path (& mut tb . path , levels) ; } } } Type :: ImplTrait (_) => { } Type :: Infer (_) | Type :: Never (_) => { } _ => compile_error (t . span () , "Unsupported type") , } } recurse (& mut output , levels) ; output }